import React from "react";
import { graphql } from "gatsby";
import Layout from "../components/layout/layout";
import PostCard from "../components/postCard";
import { SEO as Seo } from "../components/seo";
import { seriesPath } from "../lib/series.cjs";
export default function SeriesPage({ data, pageContext: { title } }) {
  return <Layout>
    <section className="page-intro">
      <h1>{title}</h1>
      <p>Follow the parts in order. Each article takes you through the next step.</p>
    </section>
    <PostCard nodes={data.allMdx.nodes} />
  </Layout>;
}
export const query = graphql`
  query SeriesArticles($series: String!) {
    allMdx(filter: {frontmatter: {series: {eq: $series}}}, sort: {frontmatter: {seriesOrder: ASC}}) {
      nodes { ...PostCardData }
    }
  }
`;
export const Head = ({ pageContext: { series, title } }) => <Seo
  title={title} description={`Step-by-step tutorials in the ${title} series.`} pathname={seriesPath(series)} />;
